  UNION ALL
  SELECT 'BATCH_AUDIT' AS MENU_ID, 'BATCH' AS PARENT_MENU_ID, 'Audit / Evidence' AS MENU_NAME, '/adm#batch-audit' AS MENU_PATH, 514 AS SORT_ORDER, 'Y' AS USE_YN, 'SYSTEM' AS created_by, 'SYSTEM' AS updated_by FROM dual
